const c = document.createElement('canvas');
const ctx = c.getContext('2d');
c.width = el.offsetWidth || 400;
c.height = el.offsetHeight || 500;
el.appendChild(c);
const W = c.width, H = c.height;
const CX = W / 2, CY = H / 2;

const particles = Array.from({length: 300}, (_, i) => {
  const angle = Math.random() * Math.PI * 2;
  const radius = Math.random() * Math.min(W, H) * 0.45 + 20;
  return {
    angle, radius,
    speed: (0.008 + Math.random() * 0.015) * (Math.random() < 0.5 ? 1 : -1),
    size: Math.random() * 2 + 0.5,
    hue: 260 + Math.random() * 60,
    alpha: Math.random() * 0.8 + 0.2
  };
});

function draw() {
  ctx.fillStyle = 'rgba(0,0,0,0.06)';
  ctx.fillRect(0, 0, W, H);

  // Center glow
  const grd = ctx.createRadialGradient(CX, CY, 0, CX, CY, 40);
  grd.addColorStop(0, 'rgba(168,85,247,0.8)');
  grd.addColorStop(0.4, 'rgba(124,58,237,0.3)');
  grd.addColorStop(1, 'transparent');
  ctx.beginPath();
  ctx.arc(CX, CY, 40, 0, Math.PI * 2);
  ctx.fillStyle = grd;
  ctx.fill();

  particles.forEach(p => {
    p.angle += p.speed;
    p.radius -= 0.08;
    if (p.radius < 5) {
      p.radius = Math.random() * Math.min(W, H) * 0.45 + 20;
      p.angle = Math.random() * Math.PI * 2;
    }
    const x = CX + Math.cos(p.angle) * p.radius;
    const y = CY + Math.sin(p.angle) * p.radius * 0.5;
    ctx.beginPath();
    ctx.arc(x, y, p.size, 0, Math.PI * 2);
    ctx.fillStyle = `hsla(${p.hue}, 90%, 70%, ${p.alpha})`;
    ctx.shadowColor = `hsl(${p.hue}, 90%, 60%)`;
    ctx.shadowBlur = 6;
    ctx.fill();
  });
  requestAnimationFrame(draw);
}
draw();

