const el = document.getElementById('container');
const c = document.createElement('canvas');
const ctx = c.getContext('2d');
c.width = Math.min(el.offsetWidth || 400, 400);
c.height = el.offsetHeight || 500;
el.appendChild(c);
const W = c.width, H = c.height;
let t = 0;

function draw() {
  ctx.fillStyle = 'rgba(5,5,15,0.15)';
  ctx.fillRect(0, 0, W, H);
  const cx = W / 2;
  const nodes = 28;
  const spacing = H / nodes;

  for (let i = 0; i < nodes; i++) {
    const y = i * spacing - (t % spacing);
    const phase = (i / nodes) * Math.PI * 4 + t * 0.04;
    const amp = W * 0.28;
    const x1 = cx + Math.cos(phase) * amp;
    const x2 = cx + Math.cos(phase + Math.PI) * amp;
    const z1 = Math.sin(phase);
    const z2 = Math.sin(phase + Math.PI);
    const r1 = 5 + z1 * 3;
    const r2 = 5 + z2 * 3;
    const a1 = 0.4 + z1 * 0.5;
    const a2 = 0.4 + z2 * 0.5;

    // Connecting rung
    if (i % 2 === 0) {
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.strokeStyle = `rgba(6,182,212,0.35)`;
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }

    // Strand 1
    ctx.beginPath();
    ctx.arc(x1, y, Math.max(r1, 1), 0, Math.PI * 2);
    ctx.fillStyle = `rgba(167,139,250,${a1})`;
    ctx.shadowColor = '#a78bfa';
    ctx.shadowBlur = r1 * 3;
    ctx.fill();

    // Strand 2
    ctx.beginPath();
    ctx.arc(x2, y, Math.max(r2, 1), 0, Math.PI * 2);
    ctx.fillStyle = `rgba(6,182,212,${a2})`;
    ctx.shadowColor = '#06b6d4';
    ctx.shadowBlur = r2 * 3;
    ctx.fill();
  }

  t += 1.2;
  requestAnimationFrame(draw);
}
draw();

