const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;background:transparent;display:flex;align-items:center;justify-content:center;overflow:hidden;';

const wrapper = document.createElement('div');
wrapper.className = 'planet-wrapper';

const planet = document.createElement('div');
planet.className = 'planet';

const ring = document.createElement('div');
ring.className = 'planet-ring';

planet.appendChild(ring);
wrapper.appendChild(planet);
c.appendChild(wrapper);

let isDragging = false;
let startX, startY;
let rotX = 0, rotY = 0;

// ગ્રહને ધીમે ધીમે ફેરવવાનું ફંક્શન
setInterval(() => {
  if(!isDragging) {
    rotY += 0.4;
    planet.style.transform = `rotateX(${rotX}deg) rotateY(${rotY}deg)`;
  }
}, 30);

// યુઝર જ્યારે ટચ કરે અને ફેરવે ત્યારે
planet.addEventListener('pointerdown', (e) => {
  isDragging = true;
  startX = e.clientX; startY = e.clientY;
  planet.style.boxShadow = '0 0 60px #00ffcc'; // સ્પર્શ કરવાથી નિયોન ગ્લો 
  ring.style.borderColor = '#00ffcc';
});

document.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const deltaX = e.clientX - startX;
  const deltaY = e.clientY - startY;
  rotY += deltaX * 0.7; // ડાબે-જમણે ફેરવવા
  rotX -= deltaY * 0.7; // ઉપર-નીચે ફેરવવા
  planet.style.transform = `rotateX(${rotX}deg) rotateY(${rotY}deg)`;
  startX = e.clientX; startY = e.clientY;
});

document.addEventListener('pointerup', () => {
  if(isDragging) {
    isDragging = false;
    planet.style.boxShadow = '0 0 30px #ff7e5f'; // ગ્લો પાછો નોર્મલ
    ring.style.borderColor = 'rgba(0, 255, 204, 0.4)';
  }
});

