const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:#000000;overflow:hidden;cursor:crosshair;';

// સ્ક્રીન પર ગમે ત્યાં ટચ કરવાથી રિપલ બનશે
c.addEventListener('pointerdown', (e) => {
  const rect = c.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  const ripple = document.createElement('div');
  ripple.className = 'ripple-wave';
  ripple.style.left = `${x}px`;
  ripple.style.top = `${y}px`;
  ripple.style.width = '100px';
  ripple.style.height = '100px';

  // દરેક ટચ માટે અલગ અલગ નિયોન કલર્સ
  const colors = [
    'rgba(0, 255, 204, 0.8)', 
    'rgba(255, 0, 128, 0.8)', 
    'rgba(155, 0, 255, 0.8)',
    'rgba(255, 255, 0, 0.8)',
    'rgba(0, 150, 255, 0.8)'
  ];
  const randomColor = colors[Math.floor(Math.random() * colors.length)];

  ripple.style.background = `radial-gradient(circle, ${randomColor} 0%, transparent 70%)`;
  ripple.style.boxShadow = `0 0 30px ${randomColor}`;

  c.appendChild(ripple);

  // એનિમેશન પૂરું થયા પછી DOM માંથી દૂર કરવા
  setTimeout(() => {
    ripple.remove();
  }, 1000);
});

